CREATE TABLE IF NOT EXISTS arenaQuotes(id CHAR(36) NOT NULL PRIMARY KEY,userId BIGINT UNSIGNED NOT NULL,config JSON NOT NULL,serverSeed CHAR(64) NOT NULL,serverSeedHash CHAR(64) NOT NULL,usedRoomId BIGINT UNSIGNED NULL,expiresAt DATETIME(3) NOT NULL,createdAt TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),KEY owner_expiry(userId,expiresAt)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS arenaBattles(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,ownerId BIGINT UNSIGNED NOT NULL,quoteId CHAR(36) NOT NULL,config JSON NOT NULL,serverSeed CHAR(64) NOT NULL,serverSeedHash CHAR(64) NOT NULL,privateKey CHAR(32) NULL,state VARCHAR(12) NOT NULL DEFAULT 'WAITING',jointSeed CHAR(64) NULL,outcomes JSON NULL,settlement JSON NULL,startsAt DATETIME(3) NULL,endsAt DATETIME(3) NULL,closedAt DATETIME(3) NULL,expiresAt DATETIME(3) NOT NULL,createdAt TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY quoted_once(quoteId),KEY lobby(state,id),KEY due(state,endsAt),KEY owner_rooms(ownerId,state)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS arenaSeats(roomId BIGINT UNSIGNED NOT NULL,seatNo INT NOT NULL,userId BIGINT UNSIGNED NOT NULL,clientSeed VARCHAR(128) NOT NULL,stake DECIMAL(18,2) NOT NULL,payout DECIMAL(18,2) NOT NULL DEFAULT 0,PRIMARY KEY(roomId,seatNo),UNIQUE KEY one_seat(roomId,userId)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS arenaActions(userId BIGINT UNSIGNED NOT NULL,requestId CHAR(36) NOT NULL,fingerprint CHAR(64) NOT NULL,result JSON NOT NULL,createdAt TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(userId,requestId)) ENGINE=InnoDB;
